    <section id="acces" class="bg-cream py-20 sm:py-24 lg:py-32"><div class="mx-auto max-w-[1380px] px-4 sm:px-6 lg:px-8"><div class="reveal grid gap-6 lg:grid-cols-2 lg:items-end"><div><p class="text-[10px] font-bold uppercase tracking-[.24em] text-pine-700">Cum ajungi</p><h2 class="mt-3 font-display text-4xl font-semibold tracking-[-.035em] sm:text-5xl lg:text-6xl">Mai aproape decât pare.</h2></div><p class="max-w-xl text-base leading-7 text-pine-900/60 lg:justify-self-end">Nordvale este la 38 de minute de oraș. Alege varianta care îți lasă energia pentru parc, nu pentru drum.</p></div><div class="mt-10 grid gap-4 lg:grid-cols-3"><article class="reveal rounded-[28px] bg-pine-950 p-6 text-white sm:p-7"><div class="flex items-start justify-between"><span class="grid h-12 w-12 place-items-center rounded-full bg-acid text-pine-950"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 17h14M6 17l1-8h10l1 8M8 9l1-3h6l1 3"/><circle cx="8" cy="18" r="1"/><circle cx="16" cy="18" r="1"/></svg></span><span class="text-xs font-bold text-acid">38 min</span></div><h3 class="mt-7 font-display text-3xl">Cu mașina</h3><p class="mt-3 text-sm leading-6 text-white/55">Urmează DN17 până la ieșirea Valea Rece, apoi indicatoarele Nordvale pentru 4 km.</p><div class="mt-6 border-t border-white/10 pt-5 text-sm"><div class="flex justify-between gap-3"><span class="text-white/45">Parcare</span><span class="font-semibold">gratuită</span></div><div class="mt-2 flex justify-between gap-3"><span class="text-white/45">Încărcare EV</span><span class="font-semibold">6 stații</span></div></div></article><article class="reveal reveal-delay-1 rounded-[28px] border border-pine-900/10 bg-oat p-6 sm:p-7"><div class="flex items-start justify-between"><span class="grid h-12 w-12 place-items-center rounded-full bg-pine-900 text-acid"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="2"><path d="M5 5h14v11H5zM7 16v3m10-3v3M8 19h8"/><circle cx="8" cy="13" r="1"/><circle cx="16" cy="13" r="1"/></svg></span><span class="text-xs font-bold text-pine-700">din oră în oră</span></div><h3 class="mt-7 font-display text-3xl">Nordvale Shuttle</h3><p class="mt-3 text-sm leading-6 text-pine-900/60">Plecare din Piața Centrală la fix și întoarcere la și jumătate, în weekend și vacanțe.</p><div class="mt-6 border-t border-pine-900/10 pt-5 text-sm"><div class="flex justify-between gap-3"><span class="text-pine-900/45">Primul shuttle</span><span class="font-semibold">08:00</span></div><div class="mt-2 flex justify-between gap-3"><span class="text-pine-900/45">Ultima întoarcere</span><span class="font-semibold">20:30</span></div></div></article><article class="reveal reveal-delay-2 rounded-[28px] border border-pine-900/10 bg-white p-6 sm:p-7"><div class="flex items-start justify-between"><span class="grid h-12 w-12 place-items-center rounded-full bg-ember text-pine-950"><svg viewBox="0 0 24 24" class="h-6 w-6" fill="none" stroke="currentColor" stroke-width="2"><circle cx="7" cy="17" r="3"/><circle cx="17" cy="17" r="3"/><path d="m7 17 4-8h4l2 8M9 12h6M12 9l-2-2"/></svg></span><span class="text-xs font-bold text-ember">18 km</span></div><h3 class="mt-7 font-display text-3xl">Cu bicicleta</h3><p class="mt-3 text-sm leading-6 text-pine-900/60">Traseu marcat din oraș, cu ultimii 6 km prin pădure și rastel păzit la intrare.</p><div class="mt-6 border-t border-pine-900/10 pt-5 text-sm"><div class="flex justify-between gap-3"><span class="text-pine-900/45">Diferență nivel</span><span class="font-semibold">+240 m</span></div><div class="mt-2 flex justify-between gap-3"><span class="text-pine-900/45">Vestiare</span><span class="font-semibold">disponibile</span></div></div></article></div></div></section>

    <section id="program" class="paper-grid border-y border-pine-900/10 py-20 sm:py-24 lg:py-32"><div class="mx-auto max-w-[1380px] px-4 sm:px-6 lg:px-8"><div class="reveal grid gap-6 lg:grid-cols-[.55fr_.45fr] lg:items-end"><div><p class="text-[10px] font-bold uppercase tracking-[.24em] text-pine-700">Program & ore limită</p><h2 class="mt-3 font-display text-4xl font-semibold tracking-[-.035em] sm:text-5xl lg:text-6xl">Fiecare zonă are<br><span class="italic text-pine-700">propriul apus.</span></h2></div><div class="rounded-[24px] bg-acid p-5 text-pine-950 lg:justify-self-end"><p class="text-[9px] font-bold uppercase tracking-[.2em]">Astăzi · miercuri</p><div class="mt-2 flex items-end justify-between gap-6"><span class="font-display text-4xl">09–20</span><span class="pb-1 text-sm font-semibold">Ultima intrare 19:00</span></div></div></div><div class="mt-10 overflow-hidden rounded-[28px] border border-pine-900/10 bg-cream"><div class="overflow-x-auto scrollbar-hide"><div class="min-w-[760px]"><div class="grid grid-cols-[1.4fr_repeat(7,1fr)] border-b border-pine-900/10 bg-pine-950 px-5 py-4 text-white"><div class="text-[10px] font-bold uppercase tracking-[.2em] text-white/45">Zonă</div><div class="text-center text-xs font-bold">L</div><div class="text-center text-xs font-bold">M</div><div class="text-center text-xs font-bold text-acid">M</div><div class="text-center text-xs font-bold">J</div><div class="text-center text-xs font-bold">V</div><div class="text-center text-xs font-bold">S</div><div class="text-center text-xs font-bold">D</div></div><div class="grid grid-cols-[1.4fr_repeat(7,1fr)] items-center border-b border-pine-900/10 px-5 py-5 text-sm"><div><p class="font-semibold">Parc & rezervație</p><p class="mt-1 text-xs text-pine-900/45">acces general</p></div><div class="text-center">10–18</div><div class="text-center">10–18</div><div class="text-center font-bold text-pine-700">09–20</div><div class="text-center">09–20</div><div class="text-center">09–21</div><div class="text-center">09–21</div><div class="text-center">09–20</div></div><div class="grid grid-cols-[1.4fr_repeat(7,1fr)] items-center border-b border-pine-900/10 px-5 py-5 text-sm"><div><p class="font-semibold">Trasee suspendate</p><p class="mt-1 text-xs text-pine-900/45">ultimul start cu 90 min înainte</p></div><div class="text-center">10–17</div><div class="text-center">10–17</div><div class="text-center font-bold text-pine-700">09–18:30</div><div class="text-center">09–18:30</div><div class="text-center">09–19</div><div class="text-center">09–19</div><div class="text-center">09–18:30</div></div><div class="grid grid-cols-[1.4fr_repeat(7,1fr)] items-center px-5 py-5 text-sm"><div><p class="font-semibold">Tururi ghidate</p><p class="mt-1 text-xs text-pine-900/45">rezervația naturală</p></div><div class="text-center">12, 16</div><div class="text-center">12, 16</div><div class="text-center font-bold text-pine-700">10, 14, 17</div><div class="text-center">10, 14, 17</div><div class="text-center">10, 14, 17</div><div class="text-center">10, 12, 15, 17</div><div class="text-center">10, 12, 15, 17</div></div></div></div></div><p class="mt-4 text-sm text-pine-900/50">Program dummy pentru template. În implementarea Tixello, orele și stările zonelor vor veni din administrare.</p></div></section>

    <section id="facilitati" class="bg-pine-950 py-20 text-white sm:py-24 lg:py-32"><div class="mx-auto max-w-[1380px] px-4 sm:px-6 lg:px-8"><div class="reveal max-w-3xl"><p class="text-[10px] font-bold uppercase tracking-[.24em] text-acid">Facilități</p><h2 class="mt-3 font-display text-4xl font-semibold tracking-[-.035em] sm:text-5xl lg:text-6xl">Mai puțin de cărat.<br><span class="italic text-white/45">Mai mult de trăit.</span></h2></div><div class="mt-10 grid gap-4 sm:grid-cols-2 lg:grid-cols-12"><article class="reveal relative min-h-[360px] overflow-hidden rounded-[30px] sm:col-span-2 lg:col-span-7 lg:row-span-2 lg:min-h-[520px]"><img src="https://images.unsplash.com/photo-1526778548025-fa2f459cd5c1?w=1200&q=82" alt="Zonă de relaxare în pădure" class="absolute inset-0 h-full w-full object-cover"><div class="absolute inset-0 bg-gradient-to-t from-pine-950 via-pine-950/20 to-transparent"></div><div class="absolute bottom-0 left-0 right-0 p-6 sm:p-8"><span class="rounded-full bg-acid px-3 py-1 text-[9px] font-bold uppercase tracking-[.18em] text-pine-950">6 puncte în parc</span><h3 class="mt-4 font-display text-3xl sm:text-4xl">Apă, pauză și umbră.</h3><p class="mt-3 max-w-lg text-sm leading-6 text-white/60">Foișoare, refill gratuit, mese de picnic și zone liniștite între trasee.</p></div></article><article class="reveal reveal-delay-1 rounded-[30px] bg-acid p-6 text-pine-950 lg:col-span-5"><div class="flex items-start justify-between"><span class="text-[10px] font-bold uppercase tracking-[.2em]">Camp Kitchen</span><span class="font-display text-3xl">01</span></div><h3 class="mt-12 font-display text-3xl">Mâncare simplă, făcută aici.</h3><p class="mt-3 text-sm leading-6 text-pine-950/65">Meniu de sezon, opțiuni pentru copii, vegetariene și picnic packs comandate din aplicație.</p></article><article class="reveal reveal-delay-2 rounded-[30px] border border-white/10 bg-white/[.05] p-6 lg:col-span-5"><div class="flex items-start justify-between"><span class="text-[10px] font-bold uppercase tracking-[.2em] text-acid">Practic</span><span class="font-display text-3xl text-white/20">02</span></div><div class="mt-10 grid grid-cols-2 gap-4 text-sm"><div><p class="text-white/40">Vestiare</p><p class="mt-1 font-semibold">120 dulapuri</p></div><div><p class="text-white/40">Baby care</p><p class="mt-1 font-semibold">2 camere</p></div><div><p class="text-white/40">Wi‑Fi</p><p class="mt-1 font-semibold">zone centrale</p></div><div><p class="text-white/40">Prim ajutor</p><p class="mt-1 font-semibold">permanent</p></div></div></article><article class="reveal rounded-[30px] border border-white/10 bg-ember p-6 text-pine-950 sm:col-span-1 lg:col-span-4"><p class="text-[10px] font-bold uppercase tracking-[.2em]">Accesibilitate</p><h3 class="mt-8 font-display text-3xl">Traseu fără bariere</h3><p class="mt-3 text-sm leading-6 text-pine-950/65">2,4 km adaptați, toalete accesibile și însoțitor gratuit.</p></article><article class="reveal reveal-delay-1 rounded-[30px] border border-white/10 bg-white/[.05] p-6 sm:col-span-1 lg:col-span-4"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-acid">Companioni</p><h3 class="mt-8 font-display text-3xl">Câinii sunt bineveniți</h3><p class="mt-3 text-sm leading-6 text-white/55">În zonele deschise și pe traseele marcate, cu lesă.</p></article><article class="reveal reveal-delay-2 rounded-[30px] border border-white/10 bg-white p-6 text-pine-950 sm:col-span-2 lg:col-span-4"><p class="text-[10px] font-bold uppercase tracking-[.2em] text-pine-700">Închiriere</p><h3 class="mt-8 font-display text-3xl">Nu ai tot echipamentul?</h3><p class="mt-3 text-sm leading-6 text-pine-900/60">Pelerine, rucsacuri pentru copii, bețe trekking și power banks.</p></article></div></div></section>

    <section id="pregatire" class="bg-oat py-20 sm:py-24 lg:py-32"><div class="mx-auto max-w-[1380px] px-4 sm:px-6 lg:px-8"><div class="grid gap-8 lg:grid-cols-[.42fr_.58fr] lg:items-start"><div class="reveal lg:sticky lg:top-28"><p class="text-[10px] font-bold uppercase tracking-[.24em] text-pine-700">Înainte să pleci</p><h2 class="mt-3 font-display text-4xl font-semibold tracking-[-.035em] sm:text-5xl">Patru lucruri.<br><span class="italic text-pine-700">Atât.</span></h2><p class="mt-5 max-w-md text-base leading-7 text-pine-900/60">Nu transforma pregătirea într-o expediție. Restul îl găsești în parc.</p></div><div class="grid gap-3"><article class="reveal rounded-[24px] border border-pine-900/10 bg-cream p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-[auto_1fr_auto] sm:items-center"><span class="grid h-11 w-11 place-items-center rounded-full bg-pine-950 font-display text-lg text-acid">01</span><div><h3 class="font-semibold">Încălțăminte cu talpă aderentă</h3><p class="mt-1 text-sm leading-6 text-pine-900/55">Nu trebuie să fie tehnică. Evită sandalele și tălpile netede.</p></div><span class="hidden rounded-full bg-oat px-3 py-1 text-xs font-semibold sm:block">esențial</span></div></article><article class="reveal reveal-delay-1 rounded-[24px] border border-pine-900/10 bg-cream p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-[auto_1fr_auto] sm:items-center"><span class="grid h-11 w-11 place-items-center rounded-full bg-pine-950 font-display text-lg text-acid">02</span><div><h3 class="font-semibold">Un strat în plus</h3><p class="mt-1 text-sm leading-6 text-pine-900/55">În pădure sunt de obicei cu 3–4°C mai puțin decât în oraș.</p></div><span class="hidden rounded-full bg-oat px-3 py-1 text-xs font-semibold sm:block">recomandat</span></div></article><article class="reveal reveal-delay-2 rounded-[24px] border border-pine-900/10 bg-cream p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-[auto_1fr_auto] sm:items-center"><span class="grid h-11 w-11 place-items-center rounded-full bg-pine-950 font-display text-lg text-acid">03</span><div><h3 class="font-semibold">Biletul pe telefon</h3><p class="mt-1 text-sm leading-6 text-pine-900/55">Codul QR funcționează și fără semnal după ce a fost descărcat.</p></div><span class="hidden rounded-full bg-oat px-3 py-1 text-xs font-semibold sm:block">obligatoriu</span></div></article><article class="reveal reveal-delay-3 rounded-[24px] border border-pine-900/10 bg-cream p-5 sm:p-6"><div class="grid gap-4 sm:grid-cols-[auto_1fr_auto] sm:items-center"><span class="grid h-11 w-11 place-items-center rounded-full bg-pine-950 font-display text-lg text-acid">04</span><div><h3 class="font-semibold">Rezervă orele cu locuri limitate</h3><p class="mt-1 text-sm leading-6 text-pine-900/55">Canopy Run și tururile ghidate au intervale fixe.</p></div><span class="hidden rounded-full bg-oat px-3 py-1 text-xs font-semibold sm:block">important</span></div></article></div></div>
        <div class="reveal mt-12 overflow-hidden rounded-[30px] bg-sky p-6 sm:p-8"><div class="grid gap-8 lg:grid-cols-[.65fr_.35fr] lg:items-center"><div><p class="text-[10px] font-bold uppercase tracking-[.22em] text-pine-700">Politica meteo</p><h3 class="mt-3 font-display text-3xl sm:text-4xl">Ploaia nu închide pădurea.</h3><p class="mt-4 max-w-2xl text-sm leading-6 text-pine-900/65 sm:text-base">Activitățile continuă în ploaie ușoară. Traseele la înălțime sunt suspendate doar la furtună, vânt puternic sau alertă meteo. În acest caz, rezervarea poate fi mutată sau convertită în credit.</p></div><div class="grid grid-cols-3 gap-2 text-center"><div class="rounded-2xl bg-white/55 p-3"><span class="text-2xl">☂</span><p class="mt-2 text-xs font-semibold">Ploaie</p><p class="mt-1 text-[10px] text-pine-900/50">deschis</p></div><div class="rounded-2xl bg-white/55 p-3"><span class="text-2xl">≋</span><p class="mt-2 text-xs font-semibold">Vânt</p><p class="mt-1 text-[10px] text-pine-900/50">evaluare</p></div><div class="rounded-2xl bg-white/55 p-3"><span class="text-2xl">ϟ</span><p class="mt-2 text-xs font-semibold">Furtună</p><p class="mt-1 text-[10px] text-pine-900/50">pauză</p></div></div></div></div>
      </div></section>

    <section class="bg-cream py-20 sm:py-24 lg:py-32"><div class="mx-auto max-w-4xl px-4 sm:px-6 lg:px-8"><div class="reveal text-center"><p class="text-[10px] font-bold uppercase tracking-[.24em] text-pine-700">Întrebări practice</p><h2 class="mt-3 font-display text-4xl font-semibold sm:text-5xl">Mai bine afli acum.</h2></div><div id="faqList" class="mt-10 divide-y divide-pine-900/10 border-y border-pine-900/10"><article class="faq-item"><button class="faq-toggle flex w-full items-center justify-between gap-5 py-5 text-left font-semibold sm:py-6"><span>Pot intra în parc fără rezervare?</span><span class="faq-icon grid h-8 w-8 flex-none place-items-center rounded-full border border-pine-900/15 text-xl">+</span></button><div class="faq-answer"><div><p class="pb-6 pr-10 text-sm leading-6 text-pine-900/60">Da, pentru accesul general. Experiențele cu capacitate limitată pot fi sold-out, de aceea recomandăm rezervarea lor în avans.</p></div></div></article><article class="faq-item"><button class="faq-toggle flex w-full items-center justify-between gap-5 py-5 text-left font-semibold sm:py-6"><span>Pot aduce mâncare de acasă?</span><span class="faq-icon grid h-8 w-8 flex-none place-items-center rounded-full border border-pine-900/15 text-xl">+</span></button><div class="faq-answer"><div><p class="pb-6 pr-10 text-sm leading-6 text-pine-900/60">Da. Ai la dispoziție zone de picnic. Nu sunt permise focul deschis, grătarele personale și recipientele din sticlă pe trasee.</p></div></div></article><article class="faq-item"><button class="faq-toggle flex w-full items-center justify-between gap-5 py-5 text-left font-semibold sm:py-6"><span>Ce se întâmplă dacă întârzii?</span><span class="faq-icon grid h-8 w-8 flex-none place-items-center rounded-full border border-pine-900/15 text-xl">+</span></button><div class="faq-answer"><div><p class="pb-6 pr-10 text-sm leading-6 text-pine-900/60">Pentru activitățile cu interval fix există o toleranță de 10 minute. După acest timp, echipa caută primul loc disponibil din aceeași zi.</p></div></div></article><article class="faq-item"><button class="faq-toggle flex w-full items-center justify-between gap-5 py-5 text-left font-semibold sm:py-6"><span>Există semnal și internet în tot parcul?</span><span class="faq-icon grid h-8 w-8 flex-none place-items-center rounded-full border border-pine-900/15 text-xl">+</span></button><div class="faq-answer"><div><p class="pb-6 pr-10 text-sm leading-6 text-pine-900/60">Semnalul mobil variază în rezervație. Wi‑Fi este disponibil în zona de intrare, Camp Kitchen și Forest Lab.</p></div></div></article></div></div></section>

    <section id="bilete" class="topo-dark relative overflow-hidden bg-pine-950 py-20 text-white sm:py-24"><div class="pointer-events-none absolute -right-20 -top-20 h-72 w-72 rounded-full border border-acid/15"></div><div class="relative mx-auto grid max-w-[1180px] gap-8 px-4 sm:px-6 lg:grid-cols-[1fr_auto] lg:items-center lg:px-8"><div class="reveal"><p class="text-[10px] font-bold uppercase tracking-[.24em] text-acid">Totul e pregătit</p><h2 class="mt-3 font-display text-4xl font-semibold sm:text-5xl">Tu doar alege ziua.</h2><p class="mt-4 max-w-2xl text-base leading-7 text-white/60">Biletul include accesul în parc și rezervație. Experiențele speciale se adaugă separat.</p></div><div class="reveal flex flex-col gap-3 min-[430px]:flex-row lg:flex-col"><a href="#" class="inline-flex items-center justify-center whitespace-nowrap rounded-full bg-acid px-7 py-4 font-bold text-pine-950">Alege biletele</a><a href="/experiente" class="inline-flex items-center justify-center whitespace-nowrap rounded-full border border-white/20 px-7 py-4 font-semibold">Vezi experiențele</a></div></div></section>
  </main>

  <footer class="bg-pine-950 pb-8 pt-14 text-white"><div class="mx-auto max-w-[1380px] px-4 sm:px-6 lg:px-8"><div class="grid gap-10 border-b border-white/10 pb-10 md:grid-cols-2 lg:grid-cols-4"><div><a href="/" class="flex items-center gap-3"><span class="grid h-11 w-11 place-items-center rounded-full bg-pine-800"><svg viewBox="0 0 48 48" class="h-8 w-8" fill="none"><path d="M7 35 18 11l7 14 5-10 11 20H7Z" fill="#DFFC62"/><path d="m8 37 11-10 6 6 7-8 8 12H8Z" fill="#FFFDF6"/></svg></span><span><span class="block font-display text-xl font-semibold">Nordvale</span><span class="text-[8px] font-bold uppercase tracking-[.24em] text-white/40">wild park · forest reserve</span></span></a><p class="mt-5 max-w-xs text-sm leading-6 text-white/45">Aventură controlată și natură vie, la mai puțin de o oră de oraș.</p></div><div><h3 class="text-[10px] font-bold uppercase tracking-[.22em] text-acid">Explorează</h3><div class="mt-4 grid gap-3 text-sm text-white/60"><a href="/experiente">Experiențe</a><a href="#harta">Harta parcului</a><a href="#program">Program</a><a href="#facilitati">Facilități</a></div></div><div><h3 class="text-[10px] font-bold uppercase tracking-[.22em] text-acid">Ai nevoie de ajutor?</h3><div class="mt-4 grid gap-3 text-sm text-white/60"><a href="#">Contact</a><a href="#">Întrebări frecvente</a><a href="#">Accesibilitate</a><a href="#">Regulamentul parcului</a></div></div><div><h3 class="text-[10px] font-bold uppercase tracking-[.22em] text-acid">Contact</h3><div class="mt-4 grid gap-3 text-sm text-white/60"><p>Valea Rece, km 4</p><p>+40 700 000 000</p><p>hello@nordvale.test</p></div></div></div><div class="flex flex-col gap-3 pt-6 text-xs text-white/35 sm:flex-row sm:items-center sm:justify-between"><p>© 2026 Nordvale. Date și denumiri demonstrative.</p><p>Ticketing powered by <span class="font-semibold text-acid">Tixello</span></p></div></div></footer>

  <script>
    (() => {
      'use strict';
      const $ = (selector, scope = document) => scope.querySelector(selector);
      const $$ = (selector, scope = document) => Array.from(scope.querySelectorAll(selector));
      const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

      const progress = $('#pageProgress');
      const updateProgress = () => {
        if (!progress) return;
        const max = Math.max(document.documentElement.scrollHeight - window.innerHeight, 1);
        progress.style.transform = `scaleX(${Math.min(window.scrollY / max, 1)})`;
      };
      updateProgress();
      window.addEventListener('scroll', updateProgress, { passive: true });
      window.addEventListener('resize', updateProgress);

      const reveals = $$('.reveal');
      if (reduceMotion || !('IntersectionObserver' in window)) {
        reveals.forEach(el => el.classList.add('is-visible'));
      } else {
        const observer = new IntersectionObserver(entries => {
          entries.forEach(entry => {
            if (entry.isIntersecting) {
              entry.target.classList.add('is-visible');
              observer.unobserve(entry.target);
            }
          });
        }, { threshold: 0.12, rootMargin: '0px 0px -40px' });
        reveals.forEach(el => observer.observe(el));
      }

      const route = $('#heroRoute');
      const traveler = $('#heroTraveler');
      if (route && traveler && !reduceMotion && typeof route.getTotalLength === 'function') {
        const length = route.getTotalLength();
        route.style.strokeDasharray = `${length}`;
        route.style.strokeDashoffset = `${length}`;
        route.animate([{ strokeDashoffset: length }, { strokeDashoffset: 0 }], { duration: 1800, delay: 450, easing: 'cubic-bezier(.2,.75,.2,1)', fill: 'forwards' });
        const animateTraveler = (time) => {
          const t = ((time / 9000) % 1);
          const p = route.getPointAtLength(length * t);
          traveler.setAttribute('cx', p.x);
          traveler.setAttribute('cy', p.y);
          requestAnimationFrame(animateTraveler);
        };
        requestAnimationFrame(animateTraveler);
      }

      const plannerState = { group: 'family', duration: '5', energy: 'balanced' };
      const labels = {
        group: { family: 'Familie', friends: 'Prieteni', couple: 'În doi', solo: 'Solo' },
        duration: { '3': '3 ore', '5': '5 ore', '8': 'Zi întreagă' },
        energy: { calm: 'Calm', balanced: 'Echilibrat', intense: 'Intens' }
      };
      const plans = {
        calm: [
          ['09:30','Start','Forest Lab','45 min · introducere în ecosistem'],
          ['10:30','Natură','Poteca de Mesteacăn','70 min · plimbare fără diferențe mari'],
          ['12:00','Pauză','Camp Kitchen','60 min · masă și odihnă'],
          ['13:15','Final','Lacul Mic','75 min · picnic și belvedere']
        ],
        balanced: [
          ['09:30','Start','Forest Lab','45 min · încălzire și descoperire'],
          ['10:30','Aventură','Canopy Junior','75 min · traseu asistat'],
          ['12:00','Pauză','Camp Kitchen','60 min · masă și odihnă'],
          ['13:15','Final','Valea Liniștită','75 min · plimbare și belvedere']
        ],
        intense: [
          ['09:15','Start','Canopy Run','90 min · traseu complet'],
          ['11:00','Adrenalină','Raven Zip','55 min · tiroliene rapide'],
          ['12:15','Pauză','Camp Kitchen','45 min · refacere'],
          ['13:15','Final','Ridge Trek','110 min · urcare și panoramă']
        ]
      };
      function renderPlan() {
        const title = $('#planTitle');
        const copy = $('#planCopy');
        const timeline = $('#planTimeline');
        if (title) title.textContent = `${labels.group[plannerState.group]} · ${labels.duration[plannerState.duration]} · ${labels.energy[plannerState.energy]}`;
        if (copy) {
          const messages = {
            calm: 'Un traseu aerisit, cu natură, panorame și suficient timp pentru pauze.',
            balanced: 'Un traseu cu aventură accesibilă, pauză de masă și o încheiere liniștită în rezervație.',
            intense: 'Un traseu compact, cu activități solicitante și timpi scurți între zone.'
          };
          copy.textContent = messages[plannerState.energy];
        }
        if (timeline) {
          const count = plannerState.duration === '3' ? 2 : plannerState.duration === '8' ? 4 : 4;
          timeline.innerHTML = plans[plannerState.energy].slice(0, count).map((item, index) => `<div class="rounded-2xl border border-white/10 bg-white/[.05] p-4"><div class="flex items-center justify-between"><span class="font-display text-xl">${item[0]}</span><span class="text-[9px] font-bold uppercase tracking-[.18em] ${index === 2 ? 'text-ember' : 'text-acid'}">${item[1]}</span></div><h4 class="mt-3 font-semibold">${item[2]}</h4><p class="mt-1 text-sm text-white/50">${item[3]}</p></div>`).join('');
        }
      }
      $$('[data-choice-group]').forEach(group => {
        const key = group.dataset.choiceGroup;
        $$('button[data-value]', group).forEach(button => button.addEventListener('click', () => {
          $$('button[data-value]', group).forEach(item => item.classList.remove('is-active'));
          button.classList.add('is-active');
          plannerState[key] = button.dataset.value;
          renderPlan();
        }));
      });
      const regenerate = $('#regeneratePlan');
      if (regenerate) regenerate.addEventListener('click', () => {
        renderPlan();
        if (!reduceMotion) regenerate.animate([{ transform:'rotate(0deg)' }, { transform:'rotate(360deg)' }], { duration:450, easing:'ease-out' });
      });

      const zones = {
        north: { title:'Valea Nord', description:'Canopy Run, tiroliene și punctul panoramic principal. Recomandată de la 8 ani.', meta:['8 min de la intrare','Echipament inclus'] },
        lab: { title:'Forest Lab', description:'Experimente, trasee senzoriale și activități ghidate pentru familii și copii.', meta:['4 min de la intrare','Accesibil cărucioarelor'] },
        lake: { title:'Lacul Mic', description:'Zonă de picnic, ponton, observare de păsări și trasee fără diferențe mari de nivel.', meta:['11 min de la intrare','Zonă liniștită'] },
        reserve: { title:'Rezervația', description:'Trasee ghidate prin aria protejată, cu acces în grupuri mici și ore fixe.', meta:['14 min de la intrare','Rezervare recomandată'] }
      };
      function selectZone(key) {
        const zone = zones[key];
        if (!zone) return;
        $$('.zone-button').forEach(button => button.classList.toggle('is-active', button.dataset.zone === key));
        const title = $('#zoneTitle');
        const description = $('#zoneDescription');
        const meta = $('#zoneMeta');
        if (title) title.textContent = zone.title;
        if (description) description.textContent = zone.description;
        if (meta) meta.innerHTML = zone.meta.map(item => `<span class="rounded-full border border-white/10 px-3 py-1 text-xs">${item}</span>`).join('');
      }
      $$('.zone-button').forEach(button => button.addEventListener('click', () => selectZone(button.dataset.zone)));
      $$('[data-map-zone]').forEach(node => node.addEventListener('click', () => selectZone(node.dataset.mapZone)));

      $$('.faq-toggle').forEach(toggle => toggle.addEventListener('click', () => {
        const item = toggle.closest('.faq-item');
        if (!item) return;
        const open = item.classList.contains('is-open');
        $$('.faq-item').forEach(entry => entry.classList.remove('is-open'));
        if (!open) item.classList.add('is-open');
      }));
    })();
  </script>
</body>
</html>
